<script setup lang="ts">
const props=defineProps<{warehouseId:number;start:string;end:string}>()
const {t,locale}=useI18n(),{bizErrorMessage}=useBizError()
const data=ref<any>(null),error=ref(''),loading=ref(false),page=ref(1)
const percent=(n:number|null|undefined)=>n==null?'—':(100*n).toLocaleString(locale.value,{maximumFractionDigits:1})+'%'
const number=(n:number)=>n.toLocaleString(locale.value)
let generation=0
const load=async()=>{const seq=++generation;loading.value=true;error.value='';data.value=null;const result=await httpRequest<any>('/api/warehouse/cyclecount/report/accuracy',{params:{start_date:props.start,end_date:props.end,page:page.value,per_page:10},headers:warehouseHeaders(props.warehouseId),onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}});if(seq===generation){data.value=result;loading.value=false}}
watch(()=>[props.warehouseId,props.start,props.end],()=>{page.value=1;load()});onMounted(load);onBeforeUnmount(()=>generation++)
</script>
<template><WCard class="count-accuracy" :title="t('count-accuracy.title')"><template #actions><NuxtLink to="/cyclecount">{{t('nav.cyclecount')}} →</NuxtLink></template><WAlert v-if="error" tone="block" :title="error"><template #actions><WButton @click="load">{{t('dn.list.retry')}}</WButton></template></WAlert><WEmptyState v-if="loading" :title="t('common.status.loading')"/><template v-if="data"><p class="help">{{t('count-accuracy.help',{zone:data.timezone})}}</p><div class="stats"><div><span>{{t('count-accuracy.by-line')}}</span><strong>{{percent(data.summary.line_accuracy)}}</strong><small>{{t('count-accuracy.lines',{different:number(data.summary.different),total:number(data.summary.lines)})}}</small></div><div><span>{{t('count-accuracy.by-quantity')}}</span><strong>{{percent(data.summary.quantity_accuracy)}}</strong><small>{{t('count-accuracy.quantities',{different:number(data.summary.difference),total:number(data.summary.quantity)})}}</small></div><div><span>{{t('count-accuracy.tasks')}}</span><strong>{{number(data.summary.tasks)}}</strong><small>{{t('count-accuracy.unverified',{count:number(data.summary.unverified)})}}</small></div></div><div class="months" :aria-label="t('count-accuracy.months')"><div v-for="month in data.monthly" :key="month.month" class="month"><span>{{percent(month.accuracy)}}</span><div class="bar-slot"><i v-if="month.accuracy!=null" :class="{partial:month.partial}" :style="{height:month.accuracy*100+'%'}" :title="month.month+' · '+month.different+' / '+month.lines"/></div><small>{{month.month.slice(5)}}</small></div></div><p class="help">{{t('count-accuracy.months-help')}}</p><div class="records"><NuxtLink class="w-count-record" v-for="row in data.items" :key="row.id" :to="'/cyclecount/detail/'+row.id"><span><b>{{row.name||'CC-'+row.id}}</b><small>{{row.date}}</small></span><span>{{t('count-accuracy.lines',{different:number(row.different),total:number(row.lines)})}}<small>{{t('count-accuracy.difference',{count:number(row.difference)})}}</small></span></NuxtLink><p v-if="!data.items.length" class="help">{{t('w.table.empty')}}</p></div><WPagination :page="page" :page-size="10" :total="data.total" show-total @update:page="value=>{page=value;load()}"/></template></WCard></template>
<style scoped>
.count-accuracy :deep(.w-card__header){padding:16px 24px 0}.count-accuracy :deep(.w-card__body){padding:12px 24px 20px;display:flex;flex-direction:column;gap:12px}.count-accuracy :deep(.w-card__actions) a{font-size:13px;font-weight:500;text-decoration:none;color:var(--w-link)}.help{margin:0;font-size:12px;line-height:18px;color:var(--w-text-3)}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0}.stats>div{display:flex;flex-direction:column;padding:0 16px;border-left:1px solid var(--w-line)}.stats>div:first-child{padding-left:0;border:0}.stats>div:last-child{padding-right:0}.stats span{font-size:12px;line-height:18px;color:var(--w-text-3)}.stats strong{font-size:20px;line-height:28px;font-weight:600}small{display:block;font-size:12px;line-height:18px;color:var(--w-text-3)}.months{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px;align-items:end}.month{text-align:center;font-size:12px;line-height:18px;color:var(--w-text-2)}.bar-slot{display:flex;align-items:flex-end;justify-content:center;height:84px;border-bottom:1px solid var(--w-border)}.bar-slot i{width:20px;background:#7855FE;border-radius:3px 3px 0 0}.bar-slot i.partial{background:#BFB9FE}.month small{padding-top:4px}.records>a{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:8px 0;border-top:1px solid var(--w-line);font-size:13px;line-height:20px;text-decoration:none;color:var(--w-text-1)}.records>a>span:last-child{text-align:right}.records b{font-weight:500}.records a:hover b{color:var(--w-link)}@media(max-width:500px){.stats{grid-template-columns:1fr;gap:12px}.stats>div{padding:0;border:0}}
</style>
